#pragma material(Domain = "Surface", ShadingModel = Unlit, BlendMode = "Translucent", TwoSided = true, OpacityMaskClipValue = 0.25, Backend = "Graph")
// A one-word value is written bare, anything else quoted; Backend is carried as written.
/// @name M_LpSettings
export void M_LpSettings(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = float3(1.0, 0.5, 0.25);
    Base.EmissiveColor = Color;
}
